import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { MapContainer, TileLayer, Marker, Popup } from 'react-leaflet';
import 'leaflet/dist/leaflet.css';
import L from 'leaflet';

// Fix para iconos de Leaflet
delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
    iconRetinaUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.7.1/images/marker-icon-2x.png',
    iconUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.7.1/images/marker-icon.png',
    shadowUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.7.1/images/marker-shadow.png',
});

const API_URL = window.location.hostname === 'localhost'
    ? 'http://localhost:3001'
    : 'https://requena-backend-production.up.railway.app';

const AdminCheckins = () => {
    // Icono para check-in (verde)
    const checkInIcon = new L.Icon({
        iconUrl: 'https://raw.githubusercontent.com/pointhi/leaflet-color-markers/master/img/marker-icon-2x-green.png',
        iconSize: [25, 41],
        iconAnchor: [12, 41],
        popupAnchor: [1, -34],
        shadowUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.7.1/images/marker-shadow.png',
        shadowSize: [41, 41]
    });

    // Icono para check-out (rojo)
    const checkOutIcon = new L.Icon({
        iconUrl: 'https://raw.githubusercontent.com/pointhi/leaflet-color-markers/master/img/marker-icon-2x-red.png',
        iconSize: [25, 41],
        iconAnchor: [12, 41],
        popupAnchor: [1, -34],
        shadowUrl: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.7.1/images/marker-shadow.png',
        shadowSize: [41, 41]
    });

    const [activePosition, setActivePosition] = useState([19.4326, -99.1332]);
    const [startDate, setStartDate] = useState('');
    const [endDate, setEndDate] = useState('');
    const [users, setUsers] = useState([]);
    const [expandedUser, setExpandedUser] = useState(null);
    const [checkinsMap, setCheckinsMap] = useState({});
    const navigate = useNavigate();

    useEffect(() => {
        fetchUsers();
    }, [startDate, endDate]);

    const fetchUsers = async () => {
        try {
            const queryParams = new URLSearchParams();
            if (startDate) queryParams.append('startDate', startDate);
            if (endDate) queryParams.append('endDate', endDate);

            const response = await fetch(`${API_URL}/admin/users?${queryParams}`);
            if (!response.ok) throw new Error('Error al cargar usuarios');
            const data = await response.json();
            setUsers(data);
        } catch (error) {
            console.error('Error al cargar usuarios:', error);
        }
    };

    const fetchCheckins = async (userId) => {
        if (expandedUser === userId) {
            setExpandedUser(null);
            return;
        }

        try {
            let url = `${API_URL}/admin/user-checkins/${userId}`;
            if (startDate || endDate) {
                const params = new URLSearchParams();
                if (startDate) params.append('startDate', startDate);
                if (endDate) params.append('endDate', endDate);
                url += `?${params.toString()}`;
            }

            const response = await fetch(url);
            if (!response.ok) throw new Error('Error al obtener historial de check-ins');
            const data = await response.json();
            setCheckinsMap(prev => ({ ...prev, [userId]: data }));
            setExpandedUser(userId);

            if (data.length > 0) {
                setActivePosition([data[0].latitude, data[0].longitude]);
            }
        } catch (error) {
            console.error('Error al obtener historial de check-ins:', error);
        }
    };

    return (
        <div className="p-6 bg-gray-100 min-h-screen">
            <button className="mb-4 bg-gray-700 text-white px-4 py-2 rounded" onClick={() => navigate('/admin')}>
                Volver al Panel
            </button>
            <h1 className="text-3xl font-bold mb-6">Gestión de Check-ins y Check-outs</h1>

            <div className="bg-white shadow-lg rounded-lg p-4">
                <h2 className="text-xl font-semibold mb-4">Lista de Usuarios</h2>
                <div className="flex gap-4 mb-4">
                    <div>
                        <label className="block text-sm font-medium">Fecha Inicio:</label>
                        <input
                            type="date"
                            value={startDate}
                            onChange={(e) => setStartDate(e.target.value)}
                            className="border px-2 py-1 rounded"
                        />
                    </div>
                    <div>
                        <label className="block text-sm font-medium">Fecha Fin:</label>
                        <input
                            type="date"
                            value={endDate}
                            onChange={(e) => setEndDate(e.target.value)}
                            className="border px-2 py-1 rounded"
                        />
                    </div>
                </div>
                <table className="w-full">
                    <thead>
                    <tr className="bg-gray-200">
                        <th className="p-3">Nombre</th>
                        <th className="p-3">Correo</th>
                        <th className="p-3">Acciones</th>
                    </tr>
                    </thead>
                    <tbody>
                    {users.map((user) => (
                        <React.Fragment key={user.id}>
                            <tr className="border-b">
                                <td className="p-3">{user.name}</td>
                                <td className="p-3">{user.email}</td>
                                <td className="p-3">
                                    <button
                                        onClick={() => fetchCheckins(user.id)}
                                        className="bg-blue-500 text-white px-3 py-1 rounded hover:bg-blue-600"
                                    >
                                        {expandedUser === user.id ? 'Ocultar Historial' : 'Ver Historial'}
                                    </button>
                                </td>
                            </tr>
                            {expandedUser === user.id && (
                                <tr>
                                    <td colSpan="3" className="bg-gray-50 p-4">
                                        <h3 className="text-lg font-semibold mb-2">Historial de Check-ins y Check-outs</h3>
                                        {checkinsMap[user.id]?.length === 0 ? (
                                            <p>No hay registros para este usuario.</p>
                                        ) : (
                                            <>
                                                <table className="w-full text-sm mb-4">
                                                    <thead>
                                                    <tr className="bg-gray-200">
                                                        <th className="p-2">Fecha y Hora</th>
                                                        <th className="p-2">Tipo</th>
                                                        <th className="p-2">Ubicación</th>
                                                    </tr>
                                                    </thead>
                                                    <tbody>
                                                    {checkinsMap[user.id]?.map((c) => {
                                                        const type = c.type || 'unknown';
                                                        const isCheckIn = type.toLowerCase().includes('checkin');
                                                        const rowClass = isCheckIn ? 'bg-green-50 hover:bg-green-100' : 'bg-red-50 hover:bg-red-100';

                                                        return (
                                                            <tr
                                                                key={`${user.id}-${c.timestamp}`}
                                                                className={`border-b cursor-pointer ${rowClass}`}
                                                                onClick={() => setActivePosition([c.latitude, c.longitude])}
                                                            >
                                                                <td className="p-2">{new Date(c.timestamp).toLocaleString()}</td>
                                                                <td className="p-2 font-semibold">
                                      <span className={isCheckIn ? 'text-green-600' : 'text-red-600'}>
                                        {type.toUpperCase()}
                                      </span>
                                                                </td>
                                                                <td className="p-2">{c.latitude}, {c.longitude}</td>
                                                            </tr>
                                                        );
                                                    })}
                                                    </tbody>
                                                </table>

                                                <MapContainer
                                                    center={activePosition}
                                                    zoom={12}
                                                    className="h-80 w-full"
                                                    key={`map-${user.id}`}
                                                >
                                                    <TileLayer url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png" />
                                                    {checkinsMap[user.id]?.map((c) => {
                                                        const type = c.type || 'unknown';
                                                        const isCheckIn = type.toLowerCase().includes('checkin');
                                                        const icon = isCheckIn ? checkInIcon : checkOutIcon;

                                                        return (
                                                            <Marker
                                                                key={`marker-${user.id}-${c.timestamp}`}
                                                                position={[c.latitude, c.longitude]}
                                                                icon={icon}
                                                            >
                                                                <Popup>
                                                                    <div className="text-sm">
                                                                        <p className={`font-bold ${isCheckIn ? 'text-green-600' : 'text-red-600'}`}>
                                                                            {type.toUpperCase()}
                                                                        </p>
                                                                        <p>{new Date(c.timestamp).toLocaleString()}</p>
                                                                        <p>Lat: {c.latitude.toFixed(4)}, Lng: {c.longitude.toFixed(4)}</p>
                                                                    </div>
                                                                </Popup>
                                                            </Marker>
                                                        );
                                                    })}
                                                </MapContainer>
                                            </>
                                        )}
                                    </td>
                                </tr>
                            )}
                        </React.Fragment>
                    ))}
                    </tbody>
                </table>
            </div>
        </div>
    );
};

export default AdminCheckins;
